#     · `#define` 缩进敏感? `a2/c65.py` 10 例全正常 ⟹ 排除;
#     · 嵌套 `#if` 内 `#define`? `a2/c64.py` 15 例正常 ⟹ 排除。
#   转机 = **`#error` 当 canary** (`a2/c66.py`): L1386(外层块内)/L1388/L1387/L1401 **均未触发**,
