#   最小复现 (8 行, `a2/c68.py` u2):
#       #if 1 / int a; / #else / #if 0 / int b; / #endif / int f(void){...} / #endif
#       int main(void){ return f(); }   ⟹ 修复前 rc=0 (f 泄漏), 应报「未声明 f」。
