#   根因 (条件栈三件套 后排[]/下劣[]/顺一):
#     `#else` 落入跳过分支时只置 `顺一 = 1`, **未把 `下劣[条件计数-1]` 置 0**;
#     而 `#endif` 的恢复式是 `顺一 = !下劣[层-1]` ⟹ 弹栈时按「该层条件为真 = 编译」恢复
#     ⟹ `#else` 体内那个嵌套 `#endif` 一弹栈, 后续代码全部泄漏回编译流。
#   修法 (2 处, 零新机制): `#else` 的「跳过」分支补 `下劣[条件计数-1] = 0;`
