                        #   病灶 (p215 真 bug 的 根): `表达式()` (L8280) **只到 `管道链()`** ⟹ 实际 是 assignment 级,
                        #     而 名字 却 是 C 的 `expression` (应 含 逗号); 同时 `逗号表达式()` (L8286) 是 **真** expression
                        #     (含 逗号层, 包 `建节(5)` 顺序块) —— 但 它 2026-08-24 只 为 "循环条件 顶层 逗号" 而 建, **只 在 5 处 用**
                        #     ⟹ **典型 补丁式**: 同一 个 洞 (顶层逗号 被 吞) 在 `循环` 修 一次, `返回` 上 再 踩 一次.
                        #   修法 (构造级, 三 步):
                        #     ① `表达式()` → **`赋值级()`** (282 处, 名实相符; `逗号表达式()` 用 占位符 保护 免 子串 误伤)
                        #     ② `逗号表达式()` → **`表达式()`** (升格 为 真 expression, 含 逗号层)
                        #     ③ `返回` 语句 接入 `表达式()` (无括号 形态 `返回 甲, 乙;` = 逗号表达式)
                        #   结构 分层 (甲言 特性 与 C 语义 各 就 其 位, 不 再 挤 在 一 处):
